def find_last_occurrence(A, x):
    """Write a function to find the index of the last occurrence of a given number in a sorted array."""
    lo = 0
    hi = len(A) - 1
    result = -1
    while lo <= hi:
        mid = (lo + hi) // 2
        if A[mid] == x:
            result = mid
            lo = mid + 1
        elif A[mid] < x:
            lo = mid + 1
        else:
            hi = mid - 1
    return result
